-- entity-engine partitions: generated by `cli entities plan --write`; forward-only; immutable once on origin/main.
-- Reviewed like a hand-written migration. No transaction control.

-- Lines stored before the field existed are posted lines: the engine writes the default on insert, this gives the old ones the same value.
UPDATE public."records_chat_message" SET data = data || '{"status": "posted"}'::jsonb WHERE data->>'status' IS NULL;

-- add_check public.records_chat_message:constraint:records_chat_message_status_chk: added NOT VALID, then validated
ALTER TABLE public."records_chat_message" ADD CONSTRAINT "records_chat_message_status_chk" CHECK ((data->>'status') IS NOT NULL AND ((data->>'status') IN ('posted', 'proposed', 'rejected'))) NOT VALID;
ALTER TABLE public."records_chat_message" VALIDATE CONSTRAINT "records_chat_message_status_chk";
-- create_index public.records_chat_message:index:records_chat_message_conversation_status_sent: on workspace_id, data->>'conversationid', data->>'status', data->>'sentat'desc, iddesc using btree
CREATE INDEX "records_chat_message_conversation_status_sent" ON public."records_chat_message" USING btree (workspace_id, ((data->>'conversationId')::uuid), (data->>'status'), (data->>'sentAt') DESC, id DESC);
